 "content": "def transform(grid):
    # Each non-background horizontal bar is one item; pack the 3-bars,
    # then the 2-bars, into a 2x3 count-pattern.
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    counts = {3: 0, 2: 0}
    for row in grid:
        prev = bg
        for value in row:
            if value != bg and value != prev and value in counts:
                counts[value] += 1
            prev = value
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
